/* C 端任务原型：C01/C02/C06/C07/C08，附 C09/C14 交互片段。 */
(()=>{
const {icon:I,esc:E,badge:B,yuan:Y}=UI;
let selected='single',step=1,filter='all',orderFilter='all',draft={experience:'',hand:'右手',confirm:false,terms:false};
const projects=()=>[{id:'single',name:'男子单打',people:'1 人 / 单',amount:UI.s.mode.endsWith('free')?0:60,capacity:'12 / 32 单'},{id:'double',name:'男子双打',people:'2 人 / 单',amount:UI.s.mode.endsWith('free')?0:120,capacity:'8 / 24 单'},{id:'female',name:'女子单打',people:'1 人 / 单',amount:0,capacity:'6 / 16 单'}];
const project=()=>projects().find(p=>p.id===selected)||projects()[0];
const route=()=>Auth.parts().path;
const go=r=>{if(location.hash.slice(1)===r)render();else location.hash=r};
const note=t=>`<div class="notice">${I('info')}<div>${t}</div></div>`;
const demoNote=()=>`<p class="route-note">界面原型 · 赛事、组织、人物及资金均为虚构示例；此页面不发生真实报名、付款或通知。</p>`;
function shell(body,active='events'){document.body.classList.toggle('auth-route',['login','signup','forgot','identity','admin-entry'].includes(route()));if(active==='teams')active='orders';document.getElementById('app').innerHTML=`<div class="proto"><span>界面原型 · 虚构数据</span><a href="business.html">查看运营工作台 ${I('arrow')}</a></div><header class="consumer-header"><div class="inner"><div class="brand-city">${UI.brand()}${Platform.cityMark()}</div><nav class="desktop-nav" aria-label="主导航">${[['home','首页'],['events','赛事'],['orders','我的参赛'],['me','我的']].map(([r,t])=>`<a href="#${r}" class="${active===r?'active':''}">${t}</a>`).join('')}</nav><div class="row">${Auth.header()}</div></div></header><main id="main" class="c-main">${body}${demoNote()}</main><footer class="c-footer"><span>AI运动 · 身边的运动生活</span><span>保定城市站 · 赛事 / 场馆 / 运动生活</span></footer><nav class="mobile-nav" aria-label="手机主导航">${[['home','home','首页'],['events','shuttle','赛事'],['orders','ticket','我的参赛'],['me','user','我的']].map(([r,i,t])=>`<a href="#${r}" class="${active===r?'active':''}">${I(i)}${t}</a>`).join('')}</nav>`}
window.renderConsumerShell=shell;
const crumb=t=>`<div class="crumb"><a href="#events">赛事</a>${I('chevron')}<span>${t}</span></div>`;
const stateBadge=()=>UI.normal()?B(UI.phaseLabel?UI.phaseLabel():({registration:'报名中',registration_closed:'报名已截止',ongoing:'进行中',finished:'已结束'})[UI.s.phase]):B('已取消','red');
function events(){Platform.events(shell)}
function detail(){if(UI.s.publication!=='published'&&!new URLSearchParams(location.search).has('preview')){shell(`${crumb('赛事详情')}<div class="card empty"><h3>此赛事当前不公开</h3><p>赛事已下架。已有报名可继续查看本人记录与资金进度。</p><a class="btn primary mt" href="#orders">查看我的报名</a></div>`);return}const p=project(),allowed=UI.normal()&&UI.s.phase==='registration';shell(`${crumb('赛事详情')}${new URLSearchParams(location.search).has('preview')?'<div class="notice neutral" style="margin-bottom:20px">组织授权预览 · 原型演示；正式产品需服务端授权，不能凭链接参数访问草稿。</div>':''}<section class="detail-banner"><div class="content"><div class="row">${stateBadge()}${B('羽毛球','gray')}</div><h1 class="detail-title">2026 秋季羽毛球交流赛</h1><p class="muted">城市球友的秋日相聚，让每一份热爱都有上场的机会。</p></div>${UI.art()}</section><div class="detail-layout"><div class="stack"><section class="card detail-block"><h3>赛事信息</h3><div class="info-pairs">${[['calendar','比赛时间','2026.10.24 — 10.25'],['clock','报名截止','2026.10.18 18:00 · 北京时间'],['pin','比赛地点','保定 · 城市运动馆（示例场地）'],['people','责任组织','莲池运动社（示例组织）']].map(([i,l,v])=>`<div class="info-item">${I(i)}<div><span class="muted">${l}</span>${v}</div></div>`).join('')}</div>${note('开放单打与双打项目。各成员独立注册，并由本人填写、确认参赛资料；名额按整单报名计算。')}</section><section class="card"><div class="section-head"><h3>选择参赛项目</h3><span class="small muted">费用按整单计算</span></div>${projects().map(x=>`<div class="project ${selected===x.id?'selected':''}"><label><input type="radio" name="project" value="${x.id}" ${selected===x.id?'checked':''}><div style="flex:1"><div class="between"><span class="project-title">${x.name}</span><span class="money">${x.amount===0?'免费':Y(x.amount)+' / 单'}</span></div><p class="muted small" style="margin-top:5px">${x.people} · ${x.amount===0?'明确免费版本':'收费版本 V1'}</p><div class="mini-progress"><span style="width:36%"></span></div><p class="small muted" style="margin-top:5px">${UI.normal()?'已占用 '+x.capacity:'历史占用 '+x.capacity+' · 名额已停用'}</p></div></label></div>`).join('')}</section><section class="card detail-block"><h3>报名与审核</h3><p>正式提交后占用整单名额，冻结本次名单、参赛资料及费用依据。${UI.automatic()?'本赛事无需人工审核；免费提交检查通过即成功，收费足额到账后重新检查规则与开赛窗口，条件允许才自动通过。':'本赛事需要人工审核；收费报名在承办方核对实际足额到账后才可审核通过。'}草稿不占名额，也不预付款。</p><h3 class="mt">退改说明 · 示例政策</h3><div class="policy"><ul><li>合法整单撤回、审核拒绝或赛事取消：未执行前按本次实收金额退回。</li><li>由承办方人工核对办理，示例办理时限为确认退款依据后 7 个工作日；以正式公布并冻结的政策为准。</li><li>重新提交重新竞争名额并产生独立义务，旧款不抵扣新报名。</li></ul></div></section></div><aside class="stack sticky"><section class="card side-summary"><div><p class="muted small">已选项目 · ${p.people}</p><h3 style="margin:7px 0 10px">${p.name}</h3><span class="money lg">${p.amount?Y(p.amount):'免费'}</span><span class="muted small"> / 整单</span></div><div class="line" style="margin:0"></div><p class="muted small">${UI.normal()?'报名截止：10月18日 18:00':'赛事已取消，原报名资金由承办方收尾'}</p><button class="btn primary big" data-action="register" ${allowed?'':'disabled'}>${allowed?'填写报名资料':UI.normal()?'当前不可新报名':'赛事已取消'} ${I('arrow')}</button><a href="#orders" class="btn">查看我的报名</a><p class="entry-note">正式提交前不占名额、不需要付款。</p></section><section class="card"><h3>联系承办方</h3><dl class="kv mt"><dt>收款责任主体</dt><dd>莲池运动社（示例）</dd><dt>付款方式</dt><dd>承办方收款码 · 人工核对</dd><dt>赛事联系人</dt><dd>赛事服务人员（示例）</dd><dt>联系渠道</dt><dd>示例渠道；正式上线前配置</dd></dl><p class="small muted mt">办赛准入不等同于主体或官方资质验真。</p></section></aside></div>${UI.scenarios()}<div class="mobile-apply"><div><span class="small muted">${p.name} · 整单</span><strong class="money">${p.amount?Y(p.amount):"免费"}</strong></div><button class="btn primary" data-action="register" ${allowed?"":"disabled"}>${allowed?"填写报名":"当前不可报名"} ${I("arrow")}</button></div>`)}
function registration(){const p=project();let body='';if(step===1)body=`<h3>本人参赛资料</h3><p class="small muted" style="margin:7px 0 22px">基础资料来自当前本人档案。本次赛事字段仅用于此报名，不复制其他赛事答案。</p><div class="form-grid"><label class="label"><span>本人姓名</span><input value="林一（虚构示例）" readonly></label><label class="label"><span>出生日期</span><input value="2000-06-18" readonly></label><label class="label"><span>常用持拍手 <b>*</b></span><select id="hand"><option ${draft.hand==='右手'?'selected':''}>右手</option><option ${draft.hand==='左手'?'selected':''}>左手</option></select></label><label class="label"><span>参赛经验（年）· 选填</span><input id="experience" type="number" min="0" value="${E(draft.experience)}" placeholder="请输入年数"></label></div><div class="line"></div><label class="checkline"><input id="self-confirm" type="checkbox" ${draft.confirm?'checked':''}><span>我已核对并确认本人本次参赛资料。</span></label><p class="field-error" id="form-error"></p>${p.id==='double'?`<div class="member"><div class="row"><span class="avatar">周</span><div>周末球友（示例）<p class="muted small">成员需本人填写确认，发起人只看完成情况</p></div></div>${B('本人已确认')}</div><p class="entry-note mt">本场景模拟成员已自行确认。待确认场景可通过下方按钮查看，不代替成员确认。</p><button class="btn text" data-action="invite">查看待确认邀请场景</button>`:''}`;else body=`<h3>核对本次报名</h3><dl class="kv mt"><dt>参赛项目</dt><dd>${p.name} · ${p.people}</dd><dt>本次名单</dt><dd>${p.id==='double'?'林一、周末球友（均为示例）':'林一（示例）'}</dd><dt>整单费用</dt><dd class="money">${p.amount?Y(p.amount):'免费'}</dd><dt>审核方式</dt><dd>${UI.automatic()?'无需人工审核':'人工审核'}</dd><dt>费用依据</dt><dd>${p.amount?'收费':'免费'}版本 V1 · 退改说明快照</dd></dl><div class="line"></div>${note(p.amount?'正式提交后即可付款，无需先等待审核。付款声明不等于实际到账或资格通过。':'本项目明确免费，不需要付款。'+(UI.automatic()?'提交检查通过后即可取得资格。':'提交后等待承办方审核。'))}<label class="checkline mt"><input id="terms" type="checkbox" ${draft.terms?'checked':''}><span>我已阅读赛事说明、整单收费及退改规则，确认正式提交本次报名。</span></label><p id="form-error" class="field-error"></p>`;
shell(`${crumb('填写报名')}<div class="form-area"><span class="eyebrow">2026 秋季羽毛球交流赛</span><h1 style="font-size:28px;margin-top:8px">${p.name}报名</h1><div class="steps"><div class="step ${step===1?'active':''}"><i>1</i>填写与确认</div><div class="step ${step===2?'active':''}"><i>2</i>核对并提交</div><div class="step"><i>3</i>查看办理进度</div></div><section class="card">${body}<div class="actions"><button class="btn left" data-action="${step===1?'back-detail':'previous'}">${step===1?'返回赛事':'上一步'}</button><button class="btn primary big" data-action="${step===1?'next':'submit'}">${step===1?'下一步，核对报名':'正式提交报名'} ${I('arrow')}</button></div></section><div class="notice neutral mt">${I('lock')}<span>草稿不占名额。正式提交时将检查当前窗口、成员确认版本及剩余名额。</span></div></div>`)}
function orders(){const list=UI.myOrders().filter(o=>orderFilter==='all'||(orderFilter==='active'&&['submitted','approved'].includes(o.status))||(orderFilter==='history'&&['withdrawn','rejected'].includes(o.status)));shell(`<div class="between"><div><span class="eyebrow">我的参赛 · 参赛记录</span><h1 style="font-size:28px;margin-top:8px">我的参赛</h1></div><a class="btn" href="#events">发现赛事 ${I('arrow')}</a></div><div class="personal-shortcuts"><span>我的参赛</span><a href="#orders" class="active">报名与进度</a><a href="#teams">我的队伍</a><a href="#me">赛果与证明入口 ${I('chevron')}</a></div><div class="tabbar">${[['all','全部报名'],['active','办理中 / 已通过'],['history','已撤回 / 未通过']].map(([r,t])=>`<button class="${orderFilter===r?'active':''}" data-action="order-filter" data-id="${r}">${t}</button>`).join('')}</div>${list.map(o=>{const [t,c]=UI.status(o);return `<article class="card order-list-card"><div class="between"><span class="muted small">${o.id} · 提交 ${o.submitted}</span>${B(t,c)}</div><h3>2026 秋季羽毛球交流赛</h3><p class="meta">${o.unit} · ${o.members.length} 人 / 单 · 10月24日 — 10月25日</p><div class="between wrap"><span class="small">整单应付 <span class="money">${Y(o.due)}</span>　有效实收 ${Y(UI.net(o))}</span><a class="btn primary slim" href="#order/${o.id}">查看详情 ${I('arrow')}</a></div></article>`}).join('')||`<div class="card empty">${I('ticket')}<h3>这里还没有报名记录</h3><p>看看身边的赛事，找到你的下一次上场。</p><a href="#events" class="btn primary mt">发现赛事</a></div>`}${UI.scenarios()}`,'orders')}
function orderPage(id){const o=UI.order(id);if(!o||o.owner!=='me'){shell(`<div class="card empty"><h3>无法查看这条报名</h3><p>请返回本人的报名记录。</p><a href="#orders" class="btn mt">返回我的报名</a></div>`,'orders');return}const [t,c]=UI.status(o),cancel=!UI.normal(),reason=UI.withdrawReason(o);const explanation=cancel?'赛事已取消，历史报名保留。请关注承办方资金收尾进度。':o.status==='approved'?'你已取得参赛资格。参赛名单以本次提交快照为准。':o.status==='withdrawn'?'本单已撤回并释放名额。重新报名需重新确认、占位和独立付款。':!UI.beforeStart()?'审核窗口已结束，当前未取得参赛资格；实际款项由承办方核对收尾。':UI.net(o)<o.due?'请按本次费用指引付款，由承办方核对真实到账，再办理资格。':'本次资金条件已满足，等待承办方人工审核。';shell(`<div class="crumb"><a href="#orders">我的报名</a>${I('chevron')}<span>报名详情</span></div><div class="order-status ${cancel?'cancelled':c==='orange'?'warn':''}"><span class="status-icon">${I(cancel?'close':o.status==='approved'?'check':'clock')}</span><div><h2>${t}</h2><p class="muted">${explanation}</p></div></div><div class="detail-layout"><div class="stack"><section class="card"><div class="section-head"><h3>2026 秋季羽毛球交流赛</h3>${B(o.unit,'gray')}</div><dl class="kv"><dt>报名编号</dt><dd>${o.id}</dd><dt>提交时间</dt><dd>${o.submitted} · 北京时间</dd><dt>名单快照</dt><dd>${o.members.map(E).join('、')}</dd><dt>参赛时间</dt><dd>2026.10.24 — 10.25</dd><dt>费用依据</dt><dd>本次费用版本 V1 · 整单计费</dd><dt>报到 / 场次</dt><dd>${o.checked?'有成员已报到':'全单尚未报到'} / ${o.match?'已有场次关联':'无场次关联'}</dd></dl><div class="line"></div><div class="status-grid"><div class="status-item"><p>${cancel?"资格历史":"参赛资格"}</p><strong>${cancel?(o.status==="approved"?"取消前已通过":"当前取消停用"):o.status==='approved'?'审核已通过':o.status==='submitted'?'尚未通过':'报名已失效'}</strong></div><div class="status-item"><p>付款声明</p><strong>${o.due===0?'无需付款':o.declared?'已声明 · 非到账':'尚未声明'}</strong></div><div class="status-item"><p>实际退款</p><strong>${UI.refunded(o)?Y(UI.refunded(o)):UI.refundLabel(o)}</strong></div></div></section><section class="card"><div class="section-head"><h3>资金进度</h3><span class="small muted">与资格分别记录</span></div><div class="between"><span class="muted">整单应付</span><span class="money">${Y(o.due)}</span></div><div class="between mt"><span class="muted">净有效实收</span><strong>${Y(UI.net(o))}</strong></div><div class="between mt"><span class="muted">累计实际退款</span><span>${Y(UI.refunded(o))}</span></div><ul class="timeline"><li>正式提交，冻结本次依据<span class="muted">${o.submitted} · 不抵扣其他报名款项</span></li>${o.declared?'<li>用户曾提交付款声明<span class="muted">用户声明与实际到账分开</span></li>':''}${o.receipts.map(r=>`<li>${r.reversed?'原收款已冲正':'承办方已登记真实收款'} ${Y(r.amount)}<span class="muted">${E(r.time)} · ${r.reversed?'不计有效实收':'此原型仅演示记录'}</span></li>`).join('')}${o.refunds.map(r=>`<li>实际退款记录 ${Y(r.amount)}<span class="muted">${E(r.time)} · ${UI.refundLabel(o)}</span></li>`).join('')}</ul></section></div><aside class="stack sticky"><section class="card side-summary"><h3>${UI.canPay(o)?'本次付款指引':'本单资金办理'}</h3><div class="between"><span class="small muted">${UI.canPay(o)?'尚待核对金额':'净有效实收'}</span><strong class="money">${Y(UI.canPay(o)?o.due-UI.net(o):UI.net(o))}</strong></div>${UI.canPay(o)?`<div class="qr-placeholder">${I('qr')}<span class="small">收款码展示位置<br>原型不可付款</span></div><p class="small muted">收款主体：莲池运动社（示例）<br>方式：承办方收款码，人工核对</p><button class="btn primary" data-action="declare" data-id="${o.id}">${o.declared?'补充付款声明':'我已付款，提交声明'}</button><p class="entry-note">请勿向原型转账。正式产品展示经承办方核对启用的有效收款码；声明不等于到账。</p>`:note(o.due===0?'本项目明确免费，无需付款。':'普通付款入口已关闭或资金条件已满足。迟到款、异常款及退款请联系承办方核对。')}<button class="btn" data-action="contact">联系承办方</button></section><section class="card"><h3>整单办理</h3><p class="small muted mt">已通过报名须截止前、全单无人报到且无场次关联才可撤回。</p><button class="btn ${reason?'':'danger'} mt" style="width:100%" data-action="withdraw" data-id="${o.id}" ${reason?'disabled':''}>撤回整单报名</button>${reason?`<p class="entry-note mt">${reason}</p>`:''}${['withdrawn','rejected'].includes(o.status)&&UI.normal()&&UI.s.phase==='registration'?`<button class="btn primary mt" style="width:100%" data-action="resubmit" data-id="${o.id}">重新准备报名</button>`:''}</section></aside></div>${UI.scenarios()}`,'orders')}
function extra(r){if(r==='messages'){shell(`<span class="eyebrow">本人通知</span><h1 style="font-size:28px;margin:8px 0 24px">消息</h1><section class="card">${!UI.normal()?`<article class="notification"><div class="todo-icon">${I('bell')}</div><div class="content"><div class="between"><h3>秋季羽毛球交流赛已取消</h3>${B(UI.s.read?'已读':'未读',UI.s.read?'gray':'orange')}</div><p>原报名记录保留，实际资金由承办方按本次退改说明人工核对办理。</p><a class="btn text mt" data-action="read" href="#order/DEMO-1001">查看本人报名 ${I('arrow')}</a><p class="entry-note mt">站内已读、短信回执与退款进度分别记录。</p></div></article>`:`<div class="empty">${I('bell')}<h3>暂无业务通知</h3><p>赛事取消等重要通知将在这里保留。</p></div>`}</section>`,'me');return}if(r==='teams'){shell(`<span class="eyebrow">一起挥拍的伙伴</span><h1 style="font-size:28px;margin:8px 0 24px">我的队伍</h1><div class="card"><div class="between"><div class="row"><span class="avatar">周</span><div><h3>周末挥拍队（示例）</h3><p class="small muted">当前队长 · 林一（示例） · 4 名有效队员</p></div></div>${B('长期队伍')}</div><div class="line"></div>${note('队伍成员不自动成为每场比赛的参赛名单。报名时另选本次成员，并由各成员本人确认。')}<div class="actions"><button class="btn" data-action="scope" data-id="队伍成员管理">查看成员</button><button class="btn primary" data-action="team-register">代表队伍报名</button></div></div><p class="route-note">C10/C11 概念片段；C12 确定放在队伍详情内的「加入/退出记录」标签，与当前成员分开；详细界面随 C10/C11 绘制。</p>`,'teams');return}shell(`<span class="eyebrow">运动者身份</span><h1 style="font-size:28px;margin:8px 0 24px">我的</h1><div class="card"><div class="row"><span class="avatar" style="width:50px;height:50px;font-size:20px">林</span><div><h3>林一（示例账号）</h3><p class="small muted">独立本人档案 · 已验证手机号只读</p></div></div><div class="line"></div><div class="stack">${[['file','本人档案'],['shuttle','本人正式赛果'],['award','我的私人证明']].map(([i,t])=>`<button class="btn" style="justify-content:space-between" data-action="${t==='本人档案'?'profile-entry':'scope'}" data-id="${t}"><span>${I(i)} ${t}</span>${I('chevron')}</button>`).join('')}<a class="btn" style="justify-content:space-between" href="#messages"><span>${I('bell')} 消息</span>${I('chevron')}</a><a class="btn" href="business.html">切换到办赛身份 ${I('arrow')}</a><a class="btn" href="organizer.html#apply">我要办赛 ${I('arrow')}</a><button class="btn" data-auth="logout">退出登录</button></div></div>`,'me')}
function render(){UI.close();const r=route();if(!['home','events','detail','register','orders','teams','me','messages','login','signup','forgot','identity','admin-entry','future/venues','future/life'].includes(r)&&!r.startsWith('order/')){location.hash='home';return}if(Auth.render(shell)){window.scrollTo(0,0);return}const protectedPage=['register','orders','teams','me','messages'].includes(r)||r.startsWith('order/');if(protectedPage&&!Auth.requireLogin(location.hash.slice(1)))return;if(r==='register'&&!Auth.profile){location.hash=Auth.link('identity',location.hash.slice(1)).slice(1);return}const unit=Auth.parts().params.get('unit');if(['single','double','female'].includes(unit))selected=unit;if(r==='home')Platform.home(shell);else if(r.startsWith('future/'))Platform.upcoming(shell,r.split('/')[1]);else if(r==='events')events();else if(r==='detail')detail();else if(r==='register')registration();else if(r==='orders')orders();else if(r.startsWith('order/'))orderPage(r.split('/')[1]);else extra(r);window.scrollTo(0,0)}
document.addEventListener('change',e=>{if(e.target.name==='project'){selected=e.target.value;detail()}const k=e.target.dataset.scenario;if(k==='mode'){UI.reset(e.target.value);render();UI.toast('已载入另一组虚构数据；这不是修改已锁定的真实审核配置')}if(k==='phase'){UI.change(s=>s.phase=e.target.value);render()}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;
if(a==='profile-entry')go(Auth.link('identity','me').slice(1));else if(a==='filter'){filter=id;events()}else if(a==='order-filter'){orderFilter=id;orders()}else if(a==='register'){step=1;go('register?event=demo-autumn&unit='+selected)}else if(a==='back-detail')go('detail?event=demo-autumn&unit='+selected);else if(a==='previous'){step=1;registration()}else if(a==='next'){draft.hand=document.getElementById('hand').value;draft.experience=document.getElementById('experience').value;draft.confirm=document.getElementById('self-confirm').checked;if(!draft.confirm||Number(draft.experience)<0){document.getElementById('form-error').textContent='请核对资料并本人确认；参赛经验不能为负数。';return}step=2;registration()}else if(a==='submit'){if(!document.getElementById('terms').checked){document.getElementById('form-error').textContent='请先阅读并确认本次报名规则。';return}if(!UI.normal()||UI.s.phase!=='registration'){UI.toast('当前窗口不允许新提交，请重新查看赛事。');go('detail');return}const p=project();const existing=UI.myOrders().find(o=>o.unit===p.name&&['submitted','approved'].includes(o.status));if(existing){go('order/'+existing.id);UI.toast('本项目已有有效报名，已返回原记录。');return}const id='DEMO-'+Date.now().toString().slice(-7);UI.change(s=>{s.fieldsLocked=true;s.orders.unshift({id,person:'林一（示例）',owner:'me',unit:p.name,due:p.amount,status:'submitted',declared:false,members:p.id==='double'?['林一（示例）','周末球友（示例）']:['林一（示例）'],receipts:[],refunds:[],checked:false,match:false,refundState:'none',submitted:'2026-10-07 11:00'})});go('order/'+id);UI.toast('模拟正式提交成功，请查看本次资格与资金下一步。')}else if(a==='declare'){const o=UI.order(id);if(!UI.canPay(o))return;UI.modal('提交付款声明',`<div class="notice warn">${I('info')}<span>声明仅用于承办方核对，不代表真实到账。原型不可付款。</span></div><form id="declaration" class="mt"><label class="label"><span>付款人称呼 <b>*</b></span><input name="payer" required maxlength="30" placeholder="可与参赛者不同"></label><label class="label"><span>付款时间 <b>*</b></span><input name="time" type="datetime-local" required></label><label class="label"><span>备注 · 选填</span><textarea name="note" placeholder="填写方便核对的信息，不上传截图"></textarea></label><button class="btn primary" type="submit">提交声明（模拟）</button></form>`);document.getElementById('declaration').onsubmit=ev=>{ev.preventDefault();if(!UI.canPay(o)){UI.close();render();return}UI.change(()=>{o.declared=true});UI.close();orderPage(id);UI.toast('付款声明已记录；有效实收仍等待承办方核对。')}}else if(a==='withdraw'){const o=UI.order(id);if(UI.withdrawReason(o))return;UI.modal('确认撤回整单报名？',`<p>将释放本单名额并保留历史。退款按原费用依据人工办理，不会在点击撤回后自动到账。</p><p class="muted small mt">重提需当前资料/本人确认、新名额及独立付款，旧款不能抵扣。</p>`,`<button class="btn" data-action="close">暂不撤回</button><button class="btn danger" data-action="confirm-withdraw" data-id="${id}">确认撤回（模拟）</button>`)}else if(a==='confirm-withdraw'){const o=UI.order(id);if(UI.withdrawReason(o))return;UI.change(()=>{o.status='withdrawn';if(UI.net(o)>0)o.refundState='pending'});render();UI.toast('模拟整单已撤回，资金按原依据单独办理。')}else if(a==='resubmit'){const o=UI.order(id);selected=projects().find(p=>p.name===o.unit)?.id||'single';draft={experience:'',hand:'右手',confirm:false,terms:false};step=1;go('register?event=demo-autumn&unit='+selected)}else if(a==='reset'){UI.reset();render();UI.toast('已重置虚构数据。')}else if(a==='contact')UI.modal('联系承办方',`<p>责任组织：莲池运动社（示例组织）</p><p class="muted mt">正式赛事会显示承办方已确认公开的联系方式。本原型不提供真实联系电话或在线客服。</p>`);else if(a==='history')UI.modal('夏末羽毛球友谊赛',`<p>此示例赛事已结束。正式产品仅公开允许的赛事信息，本人赛果需登录后按参与关系查看。</p><p class="muted mt">本轮重点体验秋季交流赛的报名与资金流程。</p>`);else if(a==='invite')UI.modal('成员待确认场景 · C09',`<p>周末球友（示例）尚未完成本人字段确认。</p><div class="notice warn mt">${I('people')}<span>整单暂不能正式提交。发起人只能查看完成情况，不能替成员确认敏感字段。</span></div><p class="muted small mt">这是另一场景的预览；关闭后回到当前“成员已自行确认”的演示数据。</p>`);else if(a==='scope')UI.modal(id+' · 后续设计',`<p>此页面属于完整 Page Map，本轮只提供入口位置，详细交互尚未生成。</p><p class="muted mt">当前可完整体验赛事详情、报名、报名详情、付款声明及办赛工作区。</p>`);else if(a==='team-register'){selected='double';step=1;go('register?event=demo-autumn&unit='+selected);UI.toast('本轮演示选定双打名单；长期队伍授权链未模拟。')}else if(a==='read')UI.change(s=>s.read=true);
});
window.addEventListener('hashchange',render);window.addEventListener('storage',e=>{if(UI.syncFromStorage(e))render()});render();
})();

